def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import threading
    from typing import Sequence, Any

    negate = kwargs.pop('negate', False)
    retcode = 0
    stdout = b''

    try:
        partitions = partition(cmd, varargs, target_concurrency, _max_length)
    except Exception as e:
        return (1, str(e).encode('utf-8'))

    def run_cmd_partition(run_cmd):
        try:
            if color and hasattr(subprocess, 'CREATE_NEW_CONSOLE'):
                p = subprocess.Popen(run_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, creationflags=subprocess.CREATE_NEW_CONSOLE)
            else:
                p = subprocess.Popen(run_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            proc_out, _ = p.communicate()
            return p.returncode, proc_out
        except Exception as e:
            return (1, str(e).encode('utf-8'))

    threads = min(len(partitions), target_concurrency)
    with threading.ThreadPoolExecutor(max_workers=threads) as executor:
        results = executor.map(run_cmd_partition, partitions)

        for proc_retcode, proc_out in results:
            retcode |= bool(proc_retcode) ^ negate
            stdout += proc_out

    return retcode, stdout

