def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        minimal_set = set()
        for cls in classes:
            if not isinstance(cls, type):
                raise ValueError(f"Expected a class, got {cls}")
            if cls not in minimal_set:
                minimal_set.add(cls)
                minimal_set.difference_update(cls.__bases__)
        # Reorder to ensure MRO consistency
        return sorted(minimal_set, key=lambda x: classes.index(x))
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

