    # Create a dictionary to hold the base classes and their hierarchy
    class_to_bases = {}
    for cls in classes:
        class_to_bases[cls] = set(cls.__bases__)

    # Function to determine if a class is a subclass of any other class in the list
    def is_subclass_of_any(cls):
        for other in classes:
            if cls is not other and issubclass(cls, other):
                return True
        return False

    # Filter out classes that are subclasses of any other class in the list
    minimal_classes = [cls for cls in classes if not is_subclass_of_any(cls)]

    # Sort the minimal classes to maintain a consistent order
    minimal_classes.sort(key=lambda cls: cls.__name__)

    return minimal_classes

