    if d1 is None or not isinstance(d1, dict):
        raise ValueError("d1 must be a dictionary")
    if d2 is None or not isinstance(d2, dict):
        raise ValueError("d2 must be a dictionary")
    if level == 0:
        return {}

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif d1[key] != d2[key]:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict) and level != 1:
                sub_diff = difference(d1[key], d2[key], level - 1)
                if sub_diff:
                    diff[key] = sub_diff
            else:
                diff[key] = d1[key]
    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != self.ndim:
        raise ValueError("coord must be a tuple with the same dimension as the histogram")

    indices = []
    for i, c in enumerate(coord):
        if c < self.edges[i][0] or c > self.edges[i][-1]:
            return  # Ignore coordinates outside the histogram edges
        idx = np.searchsorted(self.edges[i], c, side='right') - 1
        indices.append(idx)

    self.values[tuple(indices)] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self._valid_coord(coord):
        return

    idx = self._coord_to_index(coord)
    self._counts[idx] += weight

def _valid_coord(self, coord):
    return all(self._edges[i][0] <= coord[i] < self._edges[i][-1] for i in range(self.ndim))

def _coord_to_index(self, coord):
    return tuple(np.searchsorted(self._edges[i], coord[i], side='right') - 1 for i in range(self.ndim))

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if not all(low <= c < high for c, (low, high) in zip(coord, zip(self._edges[:-1], self._edges[1:]))):
            return  # Ignore coordinates outside the histogram edges

        index = tuple(np.searchsorted(self._edges[:-1], c) for c in coord)
        self._values[index] += weight
    except (AttributeError, TypeError, ValueError):
        raise ValueError("Invalid coordinates or weight provided")

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if not all(edge[0] <= c <= edge[1] for c, edge in zip(coord, self.edges)):
            return  # Ignore coordinates outside the histogram edges
        indices = tuple(int((c - edge[0]) / (edge[1] - edge[0]) * (num_bins - 1))
                        for c, edge, num_bins in zip(coord, self.edges, self.bins_per_dim))
        self.histogram[indices] += weight
    except (TypeError, IndexError) as e:
        print(f"Error filling histogram: {e}")

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    errors = []

    for key, value in labels.items():
        try:
            if not isinstance(key, str) or not key_regex.match(key):
                errors.append({str(key): f"Label key '{key}' does not match the regex '{key_regex.pattern}'"})
        except TypeError as e:
            errors.append({str(key): str(e)})

        if isinstance(value, list):
            for v in value:
                try:
                    if not isinstance(v, str) or not value_regex.match(v):
                        errors.append({str(v): f"Label value '{v}' does not match the regex '{value_regex.pattern}'"})
                except TypeError as e:
                    errors.append({str(v): str(e)})
        else:
            try:
                if not isinstance(value, str) or not value_regex.match(value):
                    errors.append({str(value): f"Label value '{value}' does not match the regex '{value_regex.pattern}'"})
            except TypeError as e:
                errors.append({str(value): str(e)})

    if errors:
        raise ValidationError(messages=errors)

