def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
    		:class:`list`).
    """
    try:
        if isinstance(params, Mapping):
            # Assuming named parameters
            if self.SQLParams.in_style == 'named':
                out_params = {self.SQLParams.out_style % key: value for key, value in params.items()}
                formatted_sql = sql % out_params
                return formatted_sql, out_params
            else:
                raise ValueError("In-style parameters are not named, but a mapping was provided.")
        elif isinstance(params, Sequence):
            # Assuming ordinal parameters
            if self.SQLParams.in_style in ('qmark', 'numeric', 'named', 'format', 'pyformat'):
                out_params = [self.SQLParams.out_style % (i + 1) for i in range(len(params))]
                formatted_sql = sql % tuple(out_params)
                return formatted_sql, list(params)
            else:
                raise ValueError("In-style parameters are not ordinal, but a sequence was provided.")
        else:
            raise TypeError("Parameters must be a Mapping or Sequence.")
    except Exception as e:
        raise ValueError(f"Error formatting SQL: {e}") from e

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
	) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of the
		in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*many_params* (:class:`~collections.abc.Iterable`) contains each set
		of in-style parameters (*params*).

		-	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
			contains the set of in-style parameters. It maps each parameter
			(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
			is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
			If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
			*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	A :class:`list` containing each set of converted out-style
			parameters (:class:`dict` or :class:`list`).
		"""
		try:
			from_style = self.SQLParams.in_style
			to_style = self.SQLParams.out_style

			if from_style == to_style:
				return sql, list(many_params)

		 formatted_sql = sql
		 formatted_params = []

			if from_style in ('pyformat', 'named', ':'):
				for params in many_params:
					if not isinstance(params, Mapping):
						raise ValueError("Named parameters must be provided as a mapping.")
					new_params = {}
					for key in params:
						new_key = self._convert_param_name(key, from_style, to_style)
						new_params[new_key] = params[key]
					formatted_sql = self._convert_sql(formatted_sql, from_style, to_style)
					formatted_params.append(new_params)

			elif from_style in ('qmark', 'numeric', '?', '%s'):
				for params in many_params:
					if not isinstance(params, Sequence):
						raise ValueError("Ordinal parameters must be provided as a sequence.")
					new_params = [self._convert_param_name(i, from_style, to_style) for i in range(len(params))]
					formatted_sql = self._convert_sql(formatted_sql, from_style, to_style)
					formatted_params.append(new_params)

			else:
				raise ValueError(f"Unsupported parameter style: {from_style}")

			return formatted_sql, formatted_params

		except Exception as e:
			raise ValueError(f"Error formatting SQL query: {e}")

	def _convert_param_name(self, param, from_style, to_style):
		if from_style == to_style:
			return param

		if from_style in ('pyformat', 'named', ':'):
			if to_style in ('qmark', '?'):
				return '?'
			elif to_style in ('numeric', '%s'):
				return '%s'
			else:
				raise ValueError(f"Unsupported conversion from {from_style} to {to_style}")

		elif from_style in ('qmark', '?'):
			if to_style in ('pyformat', 'named', ':'):
				return f":{param}"
			elif to_style in ('numeric', '%s'):
				return '%s'
			else:
				raise ValueError(f"Unsupported conversion from {from_style} to {to_style}")

		elif from_style in ('numeric', '%s'):
			if to_style in ('pyformat', 'named', ':'):
				return f":{param}"
			elif to_style in ('qmark', '?'):
				return '?'
			else:
				raise ValueError(f"Unsupported conversion from {from_style} to {to_style}")

		else:
			raise ValueError(f"Unsupported parameter style: {from_style}")

	def _convert_sql(self, sql, from_style, to_style):
		if from_style == to_style:
			return sql

		if from_style in ('pyformat', 'named', ':'):
			if to_style in ('qmark', '?'):
				return sql.replace(':', '?')
			elif to_style in ('numeric', '%s'):
				return re.sub(r':[a-zA-Z0-9_]+', '%s', sql)
			else:
				raise ValueError(f"Unsupported conversion from {from_style} to {to_style}")

		elif from_style in ('qmark', '?'):
			if to_style in ('pyformat', 'named', ':'):
				return re.sub(r'\?', ':param', sql)
			elif to_style in ('numeric', '%s'):
				return sql.replace('?', '%s')
			else:
				raise ValueError(f"Unsupported conversion from {from_style} to {to_style}")

		elif from_style in ('numeric', '%s'):
			if to_style in ('pyformat', 'named', ':'):
				return re.sub(r'%s', ':param', sql)
			elif to_style in ('qmark', '?'):
				return sql.replace('%s', '?')
			else:
				raise ValueError(f"Unsupported conversion from {from_style} to {to_style}")

		else:
			raise ValueError(f"Unsupported parameter style: {from_style}")

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a string or bytes")

    in_style = self.SQLParams.in_style
    out_style = self.SQLParams.out_style

    if in_style == out_style:
        return sql, list(many_params)

    formatted_sql = sql
    out_params = []

    for params in many_params:
        if isinstance(params, collections.abc.Mapping):
            if in_style == 'named':
                if out_style == 'pyformat':
                    formatted_sql = formatted_sql.replace(':', '%(')
                    out_params.append(params)
                elif out_style == 'format':
                    out_params.append([params[key] for key in sorted(params)])
                    formatted_sql = re.sub(r':(\w+)', lambda m: f'%({m.group(1)})s', formatted_sql)
                elif out_style == 'qmark':
                    out_params.append([params[key] for key in sorted(params)])
                    formatted_sql = re.sub(r':(\w+)', '?', formatted_sql)
                elif out_style == 'numeric':
                    out_params.append([params[key] for key in sorted(params)])
                    formatted_sql = re.sub(r':(\w+)', lambda m: f':{sorted(params).index(m.group(1)) + 1}', formatted_sql)
            else:
                raise ValueError("Mapping type params are only supported with named in-style parameters")
        elif isinstance(params, collections.abc.Sequence):
            if in_style == 'qmark':
                if out_style == 'pyformat':
                    formatted_sql = formatted_sql.replace('?', '%s')
                    out_params = [dict(enumerate(params))]
                elif out_style == 'format':
                    out_params.append(list(params))
                elif out_style == 'numeric':
                    out_params.append(list(params))
                elif out_style == 'named':
                    raise ValueError("Sequence type params are not supported with named out-style parameters")
            elif in_style == 'numeric':
                if out_style == 'pyformat':
                    formatted_sql = re.sub(r':\d+', '%s', formatted_sql)
                    out_params = [dict(enumerate(params))]
                elif out_style == 'format':
                    out_params.append(list(params))
                elif out_style == 'qmark':
                    formatted_sql = re.sub(r':\d+', '?', formatted_sql)
                    out_params.append(list(params))
                elif out_style == 'named':
                    raise ValueError("Sequence type params are not supported with named out-style parameters")
            else:
                raise ValueError("Sequence type params are only supported with qmark or numeric in-style parameters")
        else:
            raise ValueError("params must be a Mapping or Sequence")

    return formatted_sql, out_params

