    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    parts = []
    parts.append(indent_str + "Object: " + self.__class__.__name__)
    for key, value in self.__dict__.items():
        if isinstance(value, (list, tuple)):
            parts.append(indent_str + f"{key}: [")
            for item in value:
                if hasattr(item, 'pretty'):
                    parts.append(item.pretty(indent + 2, debug))
                else:
                    parts.append(indent_str + '  ' + repr(item))
            parts.append(indent_str + "]")
        elif hasattr(value, 'pretty'):
            parts.append(indent_str + f"{key}:")
            parts.append(value.pretty(indent + 2, debug))
        else:
            parts.append(indent_str + f"{key}: {repr(value)}")
    if debug:
        parts.append(indent_str + "Debug Info: " + str(id(self)))
    return '\n'.join(parts)

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op, left, right = expr
        if op == '&':
            if right == ('|', left, '_'):
                return left
            if right == ('|', ('~', left, ()), '_'):
                return ('&', left, right[2])
        elif op == '|':
            if right == ('&', left, '_'):
                return left
            if right == ('&', ('~', left, ()), '_'):
                return ('|', left, right[2])
        return expr

    try:
        return [apply_absorption(arg) for arg in args]
    except Exception as e:
        raise ValueError(f"Error processing expression: {e}")

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    from collections import deque
    args = deque(args)
    result = []

    while args:
        expr = args.popleft()
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if isinstance(left, tuple) and len(left) == 3:
                l_op, l_left, l_right = left
                if op == '&':
                    if (l_op == '|' and l_left == right and expr == (op, left, right)):
                        result.append(left)  # A & (A | B) = A
                    elif (l_op == '|' and l_right == right and expr == (op, left, right)):
                        result.append(left)  # A & (B | A) = A
                    elif (l_op == '|' and l_left == ('~', right) and expr == (op, left, right)):
                        result.append((op, left, l_right))  # A & (~A | B) = A & B
                    elif (l_op == '|' and l_right == ('~', right) and expr == (op, left, right)):
                        result.append((op, left, l_left))  # A & (B | ~A) = A & B
                    else:
                        result.append(expr)
                elif op == '|':
                    if (l_op == '&' and l_left == right and expr == (op, left, right)):
                        result.append(left)  # A | (A & B) = A
                    elif (l_op == '&' and l_right == right and expr == (op, left, right)):
                        result.append(left)  # A | (B & A) = A
                    elif (l_op == '&' and l_left == ('~', right) and expr == (op, left, right)):
                        result.append((op, left, l_right))  # A | (~A & B) = A | B
                    elif (l_op == '&' and l_right == ('~', right) and expr == (op, left, right)):
                        result.append((op, left, l_left))  # A | (B & ~A) = A | B
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            elif isinstance(right, tuple) and len(right) == 3:
                r_op, r_left, r_right = right
                if op == '&':
                    if (r_op == '|' and r_left == left and expr == (op, left, right)):
                        result.append(left)  # (A | B) & A = A
                    elif (r_op == '|' and r_right == left and expr == (op, left, right)):
                        result.append(left)  # (B | A) & A = A
                    elif (r_op == '|' and r_left == ('~', left) and expr == (op, left, right)):
                        result.append((op, left, r_right))  # (~A | B) & A = B & A
                    elif (r_op == '|' and r_right == ('~', left) and expr == (op, left, right)):
                        result.append((op, left, r_left))  # (B | ~A) & A = B & A
                    else:
                        result.append(expr)
                elif op == '|':
                    if (r_op == '&' and r_left == left and expr == (op, left, right)):
                        result.append(left)  # (A & B) | A = A
                    elif (r_op == '&' and r_right == left and expr == (op, left, right)):
                        result.append(left)  # (B & A) | A = A
                    elif (r_op == '&' and r_left == ('~', left) and expr == (op, left, right)):
                        result.append((op, left, r_right))  # (~A & B) | A = B | A
                    elif (r_op == '&' and r_right == ('~', left) and expr == (op, left, right)):
                        result.append((op, left, r_left))  # (B & ~A) | A = B | A
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        if len(args) != 3:
            raise ValueError("args must contain exactly three expressions")

        A, operator, B = args

        # Absorption laws
        if operator == '&' and B == f'({A} | ' and args[2].endswith(')'):
            return [A]
        if operator == '|' and B == f'({A} & ' and args[2].endswith(')'):
            return [A]

        # Negative absorption laws
        if operator == '&' and B.startswith('(') and B.endswith(')'):
            inside_B = B[1:-1]
            if inside_B.startswith('~') and inside_B[1:] == A:
                return [f'{A} & {args[2]}']
        if operator == '|' and B.startswith('(') and B.endswith(')'):
            inside_B = B[1:-1]
            if inside_B.startswith('~') and inside_B[1:] == A:
                return [f'{A} | {args[2]}']

        return args

    except Exception as e:
        print(f"An error occurred: {e}")
        return args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from itertools import combinations

    def is_absorable(expr1, expr2):
        if expr1 == expr2:
            return expr1
        if expr1.startswith('~') and expr1[1:] == expr2:
            return expr1
        if expr2.startswith('~') and expr2[1:] == expr1:
            return expr2
        return None

    def apply_absorption(exprs):
        for expr1, expr2 in combinations(exprs, 2):
            if '&' in expr1 and '|' in expr2:
                parts1 = expr1.split('&')
                parts2 = expr2.split('|')
            elif '|' in expr1 and '&' in expr2:
                parts1 = expr1.split('|')
                parts2 = expr2.split('&')
            else:
                continue

            if len(parts1) != 2 or len(parts2) != 2:
                continue

            if is_absorable(parts1[0], parts2[0]):
                return parts1[0]
            if is_absorable(parts1[1], parts2[1]):
                return parts1[1]
            if is_absorable(parts1[0], parts2[1]):
                return f"{parts1[0]} & {parts1[1]}"
            if is_absorable(parts1[1], parts2[0]):
                return f"{parts1[0]} & {parts1[1]}"
        return None

    simplified = []
    while args:
        expr = args.pop(0)
        simplified.append(expr)
        absorbed = apply_absorption(simplified)
        if absorbed:
            simplified.pop()
            simplified.append(absorbed)
            args = simplified + args
            simplified = []
    return simplified

