    }

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    try:
        from dateutil.relativedelta import relativedelta
    except ImportError:
        raise ImportError("dateutil module is required for this functionality.")

    norm_kwargs = {}
    for attr in ['years', 'months', 'days', 'hours', 'minutes', 'seconds', 'microseconds']:
        value = getattr(self, attr, 0)
        if isinstance(value, float):
            int_part = int(value)
            norm_kwargs[attr] = int_part
            fractional_part = value - int_part
            next_attr_index = ['years', 'months', 'days', 'hours', 'minutes', 'seconds', 'microseconds'].index(attr) + 1
            if next_attr_index < len(['years', 'months', 'days', 'hours', 'minutes', 'seconds', 'microseconds']):
                next_attr = ['years', 'months', 'days', 'hours', 'minutes', 'seconds', 'microseconds'][next_attr_index]
                next_attr_seconds = getattr(self, next_attr, 0) if next_attr in ['seconds', 'microseconds'] else 0
                if next_attr == 'seconds':
                    norm_kwargs[next_attr] = int(next_attr_seconds + fractional_part * 86400)  # 24 * 3600
                elif next_attr == 'microseconds':
                    norm_kwargs[next_attr] = int(next_attr_seconds + fractional_part * 86400000000)  # 24 * 3600 * 1000000
                else:
                    norm_kwargs[next_attr] = int(next_attr_seconds + fractional_part * 24)  # Convert days to next unit
        else:
            norm_kwargs[attr] = value

    return relativedelta(**norm_kwargs)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
            if isinstance(result, tuple):
                return tuple(item.encode() if isinstance(item, str) else item for item in result)
            elif isinstance(result, str):
                return result.encode()
            else:
                return result
        except Exception as e:
            raise Exception(f"Error while processing tzname: {e}")
    return inner_func

