def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None")

    full_command = commands + args
    try:
        if verbose:
            print("Running command: {}".format(' '.join(full_command)))
        with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT) as process:
            output, errors = process.communicate()
            if process.returncode != 0:
                if errors:
                    raise subprocess.CalledProcessError(process.returncode, full_command, output=errors)
                else:
                    raise subprocess.CalledProcessError(process.returncode, full_command)
            if output:
                return output.decode('utf-8').strip()
    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {commands[0]}")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command failed with return code {e.returncode}: {e.cmd}\nOutput: {e.output.decode('utf-8') if e.output else 'No output'}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}") from e

