def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list) or not all(isinstance(d, str) for d in version_dirs):
        raise ValueError("version_dirs must be a list of strings.")

    root_inventory = {}
    differing_content_digests = {}

    try:
        with open(os.path.join(version_dirs[0], 'inventory.json'), 'r') as f:
            root_inventory = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Failed to load root inventory from {version_dirs[0]}: {e}")

    for version_dir in version_dirs:
        try:
            with open(os.path.join(version_dir, 'inventory.json'), 'r') as f:
                inventory = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            raise ValueError(f"Failed to load inventory from {version_dir}: {e}")

        for item, digest in inventory.items():
            if item not in root_inventory or root_inventory[item] != digest:
                if item not in differing_content_digests:
                    differing_content_digests[item] = set()
                differing_content_digests[item].add(digest)

    return differing_content_digests

