            if not isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                raise ValueError("Cannot merge non-MappingNode with MappingNode")
            existing_dict = dict(existing_value.value)
            new_dict = dict(value.value)
            for new_key, new_val in new_dict.items():
                if new_key in existing_dict:
                    if isinstance(new_val, ruamel.yaml.nodes.MappingNode) and isinstance(existing_dict[new_key], ruamel.yaml.nodes.MappingNode):
                        new_val = merge_mapping(new_key, new_val, {new_key.as_string(): existing_dict[new_key]})
                        new_val = new_val[new_key.as_string()]
                    else:
                        # Non-MappingNode values, last one wins
                        existing_dict[new_key.as_string()] = new_val
                else:
                    existing_dict[new_key.as_string()] = new_val
            merged[key.as_string()] = ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=list(existing_dict.items()))

    merged_dict = defaultdict(list)

    for key, value in nodes:
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            merge_mapping(key, value, merged_dict)
        else:
            merge_scalar(key, value, merged_dict)

    result = []
    for key, value in merged_dict.items():
        if len(value) == 1:
            result.append((next(k for k, v in nodes if k.as_string() == key), value[0]))
        else:
            if not all(isinstance(v, ruamel.yaml.nodes.MappingNode) for v in value):
                result.append((next(k for k, v in nodes if k.as_string() == key), value[-1]))
            else:
                merged_value = value[0]
                for v in value[1:]:
                    merge_mapping(key, v, {key.as_string(): merged_value})
                    merged_value = merged_dict[key.as_string()]
                result.append((next(k for k, v in nodes if k.as_string() == key), merged_value))

    return result

