def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.strip()
        suffix = size[-1].upper()
        number = size[:-1]

        # If the suffix is not a letter, the whole string is a number
        if not suffix.isalpha():
            return int(size)

        number = float(number)
        if suffix == 'K':
            return int(number * 1000)
        elif suffix == 'M':
            return int(number * 1000**2)
        elif suffix == 'G':
            return int(number * 1000**3)
        elif suffix == 'T':
            return int(number * 1000**4)
        elif suffix == 'P':
            return int(number * 1000**5)
        elif suffix == 'E':
            return int(number * 1000**6)
        elif suffix == 'Z':
            return int(number * 1000**7)
        elif suffix == 'Y':
            return int(number * 1000**8)
        else:
            raise ValueError(f"Unknown suffix: {suffix}")
    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid size format: {size}") from e

