            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip().upper()
    units = {'B': 1, 'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4, 'P': 1000**5, 'E': 1000**6, 'Z': 1000**7, 'Y': 1000**8}

    if not size:
        raise ValueError("Size string is empty")

    if size.isdigit():
        return int(size)

    if size[-1] in units:
        return int(float(size[:-1]) * units[size[-1]])

    raise ValueError("Invalid size format")

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    suffix = size[-1].upper() if size[-1].isalpha() else ''
    try:
        value = int(size[:-1]) if suffix else int(size)
    except ValueError:
        raise ValueError(f"Invalid size format: {size}")

    if suffix == 'K':
        return value * 1000
    elif suffix == 'M':
        return value * 1000**2
    elif suffix == 'G':
        return value * 1000**3
    elif suffix == 'T':
        return value * 1000**4
    elif suffix == 'P':
        return value * 1000**5
    elif suffix == 'E':
        return value * 1000**6
    elif suffix == 'Z':
        return value * 1000**7
    elif suffix == 'Y':
        return value * 1000**8
    elif suffix == '':
        return value
    else:
        raise ValueError(f"Unknown suffix: {suffix}")

