def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        if not vertices or len(vertices) < 3:
            raise ValueError("The vertices list must contain at least three points.")

        result = []
        n = len(vertices)
        for i in range(n):
            result.append((vertices[i-1], vertices[i], vertices[(i+1) % n]))

        return result
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    if not alphabet or len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must be a non-empty list of unique characters")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] if padding is None or padding == 0 else alphabet[0] * padding

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")

    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

