def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()

    def _subclasses(c):
        for subclass in c.__subclasses__():
            if subclass not in seen:
                seen.add(subclass)
                _subclasses(subclass)

    _subclasses(cls)
    return seen

