    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for subcls in sc:
            if subcls not in seen:
                queue.add(subcls)

    seen.remove(cls)
    return seen

