    try:
        return re.sub(r'^["\']|["\']$', '', name)
    except TypeError:
        raise ValueError("Input must be a string")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Regex for POSIX style splitting
        regex = r"""(['"])(?:(?=(\\?))\2.)*?\1|\S+"""
    elif platform == 0:  # Windows/CMD
        # Regex for Windows/CMD style splitting
        regex = r"""(["'])(?:(?=(\\?))\2.)*?\1|[^ \t]+"""
    else:
        raise ValueError("Unsupported platform value")

    try:
        return re.findall(regex, s)
    except Exception as e:
        raise ValueError(f"Error splitting string: {e}")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        pattern = r"""(['"])(?:(?=(\\?))\2.)*?\1|\S+"""
    elif platform == 0:  # Windows/CMD
        pattern = r"""(?:"(.*?)(?<!\\)"|'(.*?)'|(\S+))"""
    else:
        raise ValueError("Unsupported platform value")

    try:
        parts = re.findall(pattern, s)
        return [m for group in parts for m in group if m]
    except re.error as e:
        raise ValueError(f"Regex error: {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error: {e}")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Regular expression for POSIX shell-like syntax
        regex = r"""(['"])(?:(?=(\\?))\2.)*?\1|[^\s'"]+"""
    elif platform == 0:  # Windows/CMD
        # Regular expression for Windows CMD-like syntax
        regex = r"""(["'])(?:(?=(\\?))\2.)*?\1|[^ \t'"]+"""
    else:
        raise ValueError("Unsupported platform value")

    try:
        return re.findall(regex, s, re.UNICODE)
    except re.error as e:
        raise ValueError(f"Regex error: {e}") from e

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    import os
    from pathlib import Path

    try:
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"The archive at {archive_path} does not exist.")

        tmp_path = Path(tmp_path)
        tmp_path.mkdir(parents=True, exist_ok=True)

        if not filename:
            filename = os.path.basename(archive_path)

        # Determine the extract command based on the file extension
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            tar_command = ['tar', '-xzf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.tar.bz2'):
            tar_command = ['tar', '-xjf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.zip'):
            tar_command = ['unzip', archive_path, '-d', str(tmp_path)]
        else:
            raise ValueError(f"Unsupported archive format: {archive_path}")

        # Extract the archive
        subprocess.run(tar_command, check=True)

        # Return the file URL to the extracted repository
        return f"file://{tmp_path / filename}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path

    if not isinstance(tmp_path, Path):
        tmp_path = Path(tmp_path)

    try:
        # Ensure the temporary directory exists
        tmp_path.mkdir(parents=True, exist_ok=True)

        # Determine the command to extract the archive
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            command = ['tar', '-xzf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
            command = ['tar', '-xjf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.zip'):
            command = ['unzip', archive_path, '-d', str(tmp_path)]
        else:
            raise ValueError(f"Unsupported archive format: {archive_path}")

        # Execute the command to extract the archive
        subprocess.run(command, check=True)

        # Determine the path to the extracted repository
        if filename:
            repo_path = tmp_path / filename
        else:
            # Assume the archive contains a single directory
            contents = list(tmp_path.iterdir())
            if len(contents) == 1 and contents[0].is_dir():
                repo_path = contents[0]
            else:
                raise ValueError("Could not determine repository path in archive")

        # Return the file URL for the repository
        return repo_path.resolve().as_uri()

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    try:
        # Ensure the temporary directory exists
        tmp_path.mkdir(parents=True, exist_ok=True)

        # Determine the full path for the extracted files
        if filename:
            extract_path = tmp_path / filename
        else:
            extract_path = tmp_path / os.path.basename(archive_path).rsplit('.', 1)[0]

        # Uncompress the archive
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(tmp_path)], check=True)
        elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(tmp_path)], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(tmp_path)], check=True)
        else:
            raise ValueError(f"Unsupported archive type: {archive_path}")

        # Construct the file URL for the repository
        repo_url = f"file://{extract_path.resolve()}"
        return repo_url

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}: {e}")
    except Exception as e:
        raise Exception(f"An error occurred while preparing the repository: {e}")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(['git', 'check-ignore', '-v'] + ignored, universal_newlines=True)
        ignored_files = set()
        for line in output.strip().split('\n'):
            if line:
                _, _, filename = line.rpartition(' ')
                ignored_files.add(filename)
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        raise Exception(f"Error obtaining ignored files: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output, status = subprocess.getstatusoutput("git check-ignore -v {}".format(ignored))
        if status != 0:
            raise Exception("Failed to check ignored files with git")

        ignored_files = [line.split()[-1] for line in output.splitlines()]
        ignored_files = sorted(set(ignored_files))  # Sort and remove duplicates

        return ','.join(ignored_files)

    except Exception as e:
        return str(e)

def addignored(ignored):
