        return str(e)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)
    except ValueError:
        raise ValueError(f"Invalid frequency format: {frequency}")

    unit = unit.lower().rstrip('s')  # Remove trailing 's' for plural units
    timedelta_kwargs = {
        'seconds': ['second'],
        'minutes': ['minute'],
        'hours': ['hour'],
        'days': ['day'],
        'weeks': ['week'],
        'months': [30],  # Approximation for months
        'years': [365],  # Approximation for years
    }

    for time_unit, valid_units in timedelta_kwargs.items():
        if unit in valid_units:
            if time_unit in ['months', 'years']:
                return datetime.timedelta(days=int(value * valid_units[0]))
            else:
                return datetime.timedelta(**{time_unit: value})

    raise ValueError(f"Unknown time unit: {unit}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError(f"Frequency '{frequency}' cannot be parsed")

        value = int(parts[0])
        unit = parts[1].lower().rstrip('s')  # Remove trailing 's' for plural units

        if unit == 'week':
            return datetime.timedelta(weeks=value)
        elif unit == 'day':
            return datetime.timedelta(days=value)
        elif unit == 'hour':
            return datetime.timedelta(hours=value)
        elif unit == 'minute':
            return datetime.timedelta(minutes=value)
        elif unit == 'second':
            return datetime.timedelta(seconds=value)
        else:
            raise ValueError(f"Unknown time unit '{unit}' in frequency '{frequency}'")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Frequency '{frequency}' cannot be parsed: {str(e)}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.strip()
    match = re.match(r"(\d+)\s*([a-zA-Z]+)", frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    try:
        quantity = int(match.group(1))
    except ValueError:
        raise ValueError(f"Cannot parse quantity in frequency: {frequency}")

    unit = match.group(2).lower()
    delta_args = {
        'second': 'seconds',
        'minute': 'minutes',
        'hour': 'hours',
        'day': 'days',
        'week': 'weeks',
        'month': 'months',  # datetime.timedelta does not support months, treated as 30 days
        'year': 'years'   # datetime.timedelta does not support years, treated as 365 days
    }

    if unit.endswith('s'):
        unit = unit[:-1]

    if unit in delta_args:
        if unit in ['month', 'year']:
            if unit == 'month':
                return datetime.timedelta(days=quantity * 30)
            elif unit == 'year':
                return datetime.timedelta(days=quantity * 365)
        else:
            return datetime.timedelta(**{delta_args[unit]: quantity})
    else:
        raise ValueError(f"Unknown time unit in frequency: {frequency}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        return socket.gethostbyname(host) in ('127.0.0.1', '::1')
    except socket.gaierror:
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        resolved_hosts = socket.gethostbyname_ex(host)
        return '127.0.0.1' in resolved_hosts[2] or host in ('localhost', 'localhost.localdomain', '127.0.0.1')
    except socket.gaierror:
        return False

