def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    try:
        config_dir = os.path.dirname(config_filename)
        if not os.path.exists(config_dir):
            os.makedirs(config_dir, mode=0o755)
        if not overwrite and os.path.exists(config_filename):
            raise FileExistsError(f"File {config_filename} already exists and overwrite is False.")
        with open(config_filename, 'w') as config_file:
            config_file.write(rendered_config)
        os.chmod(config_filename, mode)
    except FileExistsError as e:
        raise e
    except Exception as e:
        raise OSError(f"An error occurred while writing to {config_filename}: {e}")

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    try:
        config_path = os.path.expanduser(config_filename)
        if not overwrite and os.path.isfile(config_path):
            return
        else:
            os.makedirs(os.path.dirname(config_path), exist_ok=True)
            with open(config_path, "w", mode=mode) as f:
                f.write(rendered_config)
    except OSError as e:
        raise OSError(f"Failed to write configuration to {config_path}: {str(e)}")

def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    try:
        lines = script.strip().splitlines()
        return separator.join(line.strip() for line in lines if line.strip())
    except AttributeError:
        raise ValueError("The script must be a string.")

