def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
            raise ValueError("Commands should be a list of strings.")
        if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
            raise ValueError("Arguments should be a list of strings.")

        full_command = commands + args
        stderr_redir = subprocess.DEVNULL if hide_stderr else None

        if verbose:
            print(f"Running: {' '.join(full_command)}")

        process = subprocess.Popen(full_command, cwd=cwd, env=env, stderr=stderr_redir)
        process.wait()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, full_command)

    except subprocess.CalledProcessError as e:
        raise ProgramError(f"Command {' '.join(e.cmd)} failed with return code {e.returncode}")
    except Exception as e:
        raise ProgramError(f"An error occurred: {str(e)}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        full_command = commands + args
        subprocess_kwargs = {
            'cwd': cwd,
            'env': env,
            'stderr': subprocess.DEVNULL if hide_stderr else subprocess.STDOUT,
            'stdout': subprocess.PIPE if verbose else subprocess.DEVNULL
        }
        result = subprocess.run(full_command, **subprocess_kwargs, text=True, check=True)
        if verbose:
            print(result.stdout)
        return result
    except subprocess.CalledProcessError as e:
        print(f"Command failed with return code {e.returncode}")
        if verbose:
            print(f"Error output: {e.stdout}")
        raise
    except Exception as e:
        print(f"An error occurred: {e}")
        raise

