def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import toml
    import logging
    import traceback

    config_dict = {}
    parse_errors = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            error_record = logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'msg': f'Configuration file not found: {filename}'
            })
            parse_errors.append(error_record)
            continue

        try:
            with open(filename) as f:
                config_data = toml.load(f)
            config_dict[filename] = config_data

        except Exception as e:
            error_record = logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'msg': f'Error parsing configuration file {filename}: {e}',
                'exc_info': traceback.format_exc()
            })
            parse_errors.append(error_record)

    if overrides:
        for key, value in overrides.items():
            for config in config_dict.values():
                if resolve_env and isinstance(value, str):
                    value = os.path.expandvars(value)
                config[key] = value

    return config_dict, parse_errors

