            except Exception as e:
                log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                                    msg=f"Failed to parse configuration file: {filename}. Error: {str(e)}", args=(), exc_info=True))
                continue

            if resolve_env:
