                config.update(overrides)

            config_dict[filename] = config

        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                                msg=f"Unexpected error processing configuration file: {filename}. Error: {str(e)}", args=(), exc_info=True))

    return config_dict, log_records

def _resolve_environment_variables(config):
    import os
    import re

    env_var_pattern = re.compile(r'\$\{([^}]+)\}')

    def replace_env_vars(value):
        if isinstance(value, str):
            return env_var_pattern.sub(lambda match: os.getenv(match.group(1), match.group(0)), value)
        elif isinstance(value, dict):
            return {k: replace_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [replace_env_vars(v) for v in value]
        else:
            return value

    return replace_env_vars(config)

