def _resolve_env_variables(config):
    import os
    import re

    env_var_pattern = re.compile(r'\$\{(\w+)\}')

    def replace_env_vars(match):
        env_var_name = match.group(1)
        return os.getenv(env_var_name, match.group(0))

    def resolve_dict(d):
        for key, value in d.items():
            if isinstance(value, str):
                d[key] = env_var_pattern.sub(replace_env_vars, value)
            elif isinstance(value, dict):
                resolve_dict(value)
            elif isinstance(value, list):
                for i in range(len(value)):
                    if isinstance(value[i], dict):
                        resolve_dict(value[i])
                    elif isinstance(value[i], str):
                        value[i] = env_var_pattern.sub(replace_env_vars, value[i])

    resolve_dict(config)
    return config

