    """
    try:
        if not url or not url.startswith(('http://', 'https://')):
            raise ValueError("Invalid URL provided")

        if document_path and not document_path.startswith('/'):
            raise ValueError("Document path must start with a '/'")

        default_path = "/.well-known/nodeinfo"
        path = document_path if document_path else default_path

        return {
            "links": [{
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": f"{url.rstrip('/')}{path}"
            }]
        }
    except Exception as e:
        logger.error(f"Error generating NodeInfo .well-known document: {e}")
        return None

