def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET
    from xml.parsers.expat import ExpatError

    try:
        # Try to parse as JSON
        data = json.loads(document)
        return {
            "subject": data.get('subject'),
            "hcard_url": next((link['href'] for link in data.get('links', []) if link.get('rel') == 'http://microformats.org/profile/hcard'), None),
            "seed_url": next((link['href'] for link in data.get('links', []) if link.get('rel') == 'self'), None)
        }
    except json.JSONDecodeError:
        # Fallback to parse as XRD
        try:
            root = ET.fromstring(document)
            xrd = {
                "subject": root.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text,
                "hcard_url": None,
                "seed_url": None
            }
            for link in root.findall("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
                rel = link.get("rel")
                if rel == "http://microformats.org/profile/hcard":
                    xrd["hcard_url"] = link.get("href")
                elif rel == "self":
                    xrd["seed_url"] = link.get("href")
            return xrd
        except (ET.ParseError, ExpatError):
            logger.warning("parse_diaspora_webfinger: unable to parse document")
            return {}
    except Exception as e:
        logger.error(f"parse_diaspora_webfinger: unexpected error: {e}")
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from bs4 import BeautifulSoup

    try:
        # Try to parse as JSON (new format)
        data = json.loads(document)
        return {
            "hcard_url": data['links'][0]['template'].replace('{uri}', 'acct:'),
            "public_key": data['links'][1]['href']
        }
    except (json.JSONDecodeError, KeyError, IndexError):
        # Failed to parse as JSON, try XRD (old format)
        soup = BeautifulSoup(document, 'xml')
        hcard_link = soup.find('Link', rel='http://webfinger.net/rel/hcard')
        public_key_link = soup.find('Link', rel='diaspora-public-key')
        if hcard_link and public_key_link:
            return {
                "hcard_url": hcard_link['template'].replace('{uri}', 'acct:'),
                "public_key": public_key_link['href']
            }
        else:
            logger.warning("parse_diaspora_webfinger: Could not find required links in the document.")
            return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON
        parsed_document = json.loads(document)
        return parsed_document
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XML (XRD)
        try:
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Invalid XRD document")

            links = root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')
            parsed_document = {
                'links': [
                    {link.attrib['rel']: link.attrib.get('template', link.attrib.get('href'))} for link in links
                ]
            }
            return parsed_document
        except (ET.ParseError, ValueError) as e:
            logger.warning("parse_diaspora_webfinger: failed to parse webfinger document: %s", e)
            return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try parsing as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # Fallback to parsing as XRD
        try:
            root = ET.fromstring(document)
            data = {}
            for elem in root.findall(".//xrd:Link", namespaces={"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}):
                rel = elem.get('rel')
                href = elem.get('href')
                if rel and href:
                    data[rel] = href
            return data
        except ET.ParseError:
            logger.warning("parse_diaspora_webfinger: invalid document")
            return {}

