def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import logging

    logger = logging.getLogger(__name__)
    command = ["ansible-playbook"]

    if verbose:
        command.append('-' + 'v' * verbose)

    if extra_vars:
        command.append('--extra-vars')
        command.append(' '.join(f'{k}={v}' for k, v in extra_vars.items()))

    if ansible_args:
        for key, value in ansible_args.items():
            if value is not None:
                if value is True:
                    command.append(f'--{key}')
                else:
                    command.append(f'--{key}={value}')
            else:
                command.append(f'--{key}')

    command.append(playbook_path)

    logger.debug("Executing Ansible call `%s`", " ".join(command))
    try:
        p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = p.communicate()
        if p.returncode != 0:
            logger.error("Ansible playbook failed with error: %s", stderr.decode())
            raise RuntimeError(f"Ansible reported an error when executing playbook {playbook_path}")
        return stdout.decode()
    except Exception as e:
        logger.exception("An error occurred while running ansible-playbook")
        raise e

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict with arguments
    """
    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg_name, arg_value in values_dict.items():
        try:
            action = next(action for action in parser._actions if action.dest == arg_name)
        except StopIteration:
            # If the argument is not found in the parser, skip it.
            continue

        if action.nargs == 0 and isinstance(action, argparse._StoreTrueAction):
            # Convert to boolean for store_true actions
            values_dict[arg_name] = arg_value.lower() in ['true', '1', 't', 'y', 'yes']
        elif action.type:
            # Use the type specified in the parser action
            try:
                values_dict[arg_name] = action.type(arg_value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Error converting {arg_name}: {e}")
        elif isinstance(action, argparse._StoreFalseAction):
            # Convert to boolean for store_false actions
            values_dict[arg_name] = arg_value.lower() not in ['false', '0', 'f', 'n', 'no']

